using DentalApi.Data;
using DentalApi.Models;

namespace DentalApi.Services;

internal sealed class ClinicalAuditTrail(AppDbContext db, TimeProvider clock)
{
    // Future callers must use a freshly checked scope, and commit this staged
    // metadata alongside the clinical write, or before releasing a clinical read.
    // The correlation ID must be generated by the server, not supplied as free text.
    internal ClinicalAuditEvent Stage(ClinicalEncounterScope scope, ClinicalAuditAction action, Guid correlationId)
    {
        ArgumentNullException.ThrowIfNull(scope);
        if (!Enum.IsDefined(action))
            throw new ArgumentOutOfRangeException(nameof(action));
        if (correlationId == Guid.Empty)
            throw new ArgumentException("Audit correlation is required.", nameof(correlationId));

        var entry = new ClinicalAuditEvent
        {
            ClinicId = scope.ClinicId,
            AppointmentId = scope.AppointmentId,
            ActorUserId = scope.DoctorUserId,
            Action = action,
            OccurredUtc = clock.GetUtcNow(),
            CorrelationId = correlationId
        };
        db.Add(entry);
        return entry;
    }
}
